#!/bin/bash
# GENERATED BY build/build.py - DO NOT EDIT BY HAND - sources: upstream/argosbx.sh + modules/*.sh
export LANG=en_US.UTF-8
mkdir -p "$HOME/agsbx"
# Argosbx Lifecycle Hook Engine (modules/hook.sh)
# Clean event dispatching so modules register handlers instead of
# requiring fragile string replacements inside upstream logic.

# register_hook <event_name> <handler_function>
register_hook(){
  local event="$1" handler="$2"
  [ -n "$event" ] && [ -n "$handler" ] || return 0
  local current=""
  eval "current=\"\${_AGS_HOOK_${event}:-}\""
  case " $current " in
    *" $handler "*) ;;
    *) eval "_AGS_HOOK_${event}=\"\${current:+\$current }\$handler\"" ;;
  esac
}

# run_hook <event_name> [args...]
run_hook(){
  local event="$1"
  shift || return 0
  local handlers=""
  eval "handlers=\"\${_AGS_HOOK_${event}:-}\""
  for handler in $handlers; do
    if command -v "$handler" >/dev/null 2>&1; then
      "$handler" "$@" || true
    fi
  done
}
# Incremental update state (private module).
# vars.env records the full variable set of the last successful install/rep,
# one shell-escaped assignment per line, chmod 600. It is NOT a substitute
# for sh.txt (which is display only); it is the merge source for `add`.
# vars_merge: only for `add`, called at the very top of the script, before
# the sh.txt save loop and before protocol selection, so the merged set is
# what gets saved and what gets installed. It loads vars.env only for
# variables NOT already set on the command line, so explicit values win
# and unset values inherit. It fails (exit 1) if vars.env is missing or
# the merged set selects no protocol, because proceeding would silently
# drop the old installation. Deleting a protocol is NOT done via `add`
# (unset means inherit); use `rep` for a full reset, as before.
# vars_save: called after ins() in the main install flow only, so a failed
# install never overwrites the last good state, and list/upx/ups/res/del
# (which exit before ins) never touch it. Values are single-line (the
# generator already converts egress textareas to ';' separated lines),
# and are written with %q so special characters survive a round trip.
vars_merge(){
  if [ "$1" != "add" ]; then return 0; fi
  if [ ! -s "$HOME/agsbx/vars.env" ]; then
    echo "增量更新失败：未找到上次安装的变量记录 $HOME/agsbx/vars.env，请先用完整命令安装，或用 rep 全量重置"
    exit 1
  fi
  while IFS= read -r line || [ -n "$line" ]; do
    case "$line" in ''|'#'*) continue;; esac
    name="${line%%=*}"
    case "$name" in *[!A-Za-z0-9_]*|'') continue;; esac
    # vlpt2 / vlpt_more removed: an old vars.env that still lists them
    # must not resurrect them into a merge (they are cleared anyway in
    # vlpt-comma.sh, but skipping here keeps add from re-saving them).
    case "$name" in vlpt2|vlpt_more) continue;; esac
    if [ -z "${!name+x}" ]; then eval "$line"; fi
  done < "$HOME/agsbx/vars.env"
  for v in vlpt vmpt vmtls vwpt hypt tupt xhpt vxpt anpt arpt sspt sopt nvpt xupt xcpt; do
    [ -n "${!v+x}" ] && return 0
  done
  echo "增量更新失败：合并后没有任何协议变量，请在 add 命令前至少设置一个新增或修改的协议变量"
  exit 1
}
vars_save(){
  local f="$HOME/agsbx/vars.env" tmp
  tmp="$f.tmp.$$"
  : > "$tmp" 2>/dev/null || return 1
  for v in uuid vlpt vmpt vmpt_more vmtls vmtls_more vwpt vwpt_more hypt hypt_more tupt tupt_more xhpt xhpt_more vxpt vxpt_more anpt anpt_more arpt arpt_more sspt sspt_more sopt sopt_more nvpt nvpt_more xupt xupt_more xcpt xcpt_more reym cdnym argo agn agk warp name oap ym alns certmode certsrc vlpt_kernel egress_nodes egress_bind egress_rules cfip hyjpt ippz sub subid subpt; do
    if [ -n "${!v+x}" ]; then printf '%s=%q\n' "$v" "${!v}" >> "$tmp"; fi
  done
  chmod 600 "$tmp" 2>/dev/null || true
  mv "$tmp" "$f" 2>/dev/null || return 1
}
command -v register_hook >/dev/null 2>&1 && {
  register_hook on_init vars_merge
  register_hook on_complete vars_save
}
run_hook on_init "$1"
# camouflage-blog.sh: 伪装博客部署模块
# 每台机器按 /etc/machine-id 确定性随机选一个人设（8 选 1），
# 同一台机器 rep 不变，不同机器大概率不同，避免"所有站都叫陈默"的指纹。

# 人设池：AUTHOR|SITE_NAME|TAGLINE|BIO|AVATAR|AUTHOR_PINYIN
_camouflage_personas() {
  cat << 'PERSONA_EOF'
陈默|默记|陈默的技术笔记 —— Python、Linux 与 VPS 运维的实践记录|运维工程师，喜欢用 Python 写点自动化脚本，折腾 VPS 和开源软件。这个博客记录工作里踩过的坑和学到的东西，更新不定期。|默|chenmo
林晓|晓的技术笔记|林晓的技术笔记 —— 后端开发与效率工具|写 Java 和 Go 的后端程序员，偶尔写写 Python 脚本提高效率。这里记录一些开发和运维中的实战经验。|晓|linxiao
周远|远方笔记|周远的远方笔记 —— 全栈开发的学习记录|前后端都写一点的全栈工程师，对自建服务和开源项目感兴趣，博客用来整理学习笔记。|远|zhouyuan
苏晴|晴空下|苏晴的博客 —— 前端与 Linux 日常|前端工程师，喜欢捣鼓博客主题和静态网站，也记录一些 Linux 日常使用心得。|晴|suqing
陆明|明心录|陆明的明心录 —— DevOps 实践|专注自动化运维和 CI/CD，常用 Ansible 和 Docker，博客记录工作中的实践总结。|明|luming
沈静|静水流深|沈静的技术备忘录 —— 数据与 Python|和数据打交道，写 Python 做 ETL，也折腾服务器。这个博客是我的技术备忘录。|静|shenjing
高翔|翔宇技术志|高翔的技术志 —— 架构与运维思考|十多年 IT 老兵，经历过物理机、虚拟化到云原生，写点架构思考和运维经验。|翔|gaoxiang
何欣|欣欣向荣|何欣的博客 —— Python 学习之路|Python 重度用户，从爬虫到 Web 开发都写过，博客记录学习路径上的点滴。|欣|hexin
PERSONA_EOF
}

# camouflage_pick_persona: 按机器 id 确定性选人设，设置 P_* 变量
camouflage_pick_persona() {
  local seed idx total
  seed=$(cat /etc/machine-id 2>/dev/null || hostname 2>/dev/null || echo "default")
  total=$(_camouflage_personas | wc -l)
  idx=$(echo "$seed" | cksum | awk -v n="$total" '{print $1 % n + 1}')
  local line
  line=$(_camouflage_personas | sed -n "${idx}p")
  P_AUTHOR=$(echo "$line" | cut -d'|' -f1)
  P_SITE_NAME=$(echo "$line" | cut -d'|' -f2)
  P_TAGLINE=$(echo "$line" | cut -d'|' -f3)
  P_BIO=$(echo "$line" | cut -d'|' -f4)
  P_AVATAR=$(echo "$line" | cut -d'|' -f5)
  P_AUTHOR_PINYIN=$(echo "$line" | cut -d'|' -f6)
}

# _camouflage_write <dest>: 从 stdin 读模板，替换占位符后写入 dest
_camouflage_write() {
  local _c
  _c=$(cat)
  _c="${_c//\{\{SITE_NAME\}\}/$P_SITE_NAME}"
  _c="${_c//\{\{AUTHOR\}\}/$P_AUTHOR}"
  _c="${_c//\{\{TAGLINE\}\}/$P_TAGLINE}"
  _c="${_c//\{\{BIO\}\}/$P_BIO}"
  _c="${_c//\{\{AVATAR\}\}/$P_AVATAR}"
  _c="${_c//\{\{AUTHOR_PINYIN\}\}/$P_AUTHOR_PINYIN}"
  printf '%s' "$_c" > "$1"
}

# deploy_camouflage_blog <webroot>: 部署伪装博客到 webroot
# 模板内容由 build.py 从 modules/camouflage/ 嵌入（见 CAMOUFLAGE_TEMPLATES 标记）
deploy_camouflage_blog() {
  local webroot="$1"
  [ -n "$webroot" ] || { echo "deploy_camouflage_blog: 需要 webroot 参数"; return 1; }
  camouflage_pick_persona
  mkdir -p "$webroot/posts"
  echo "伪装博客人设：$P_AUTHOR《$P_SITE_NAME》"
  _camouflage_write "$webroot/about.html" << 'CAMOUFLAGE_TPL_EOF'
