CAMOUFLAGE_TPL_EOF
  chmod -R 755 "$webroot" 2>/dev/null || true
  find "$webroot" -type f -exec chmod 644 {} \; 2>/dev/null || true
  echo "伪装博客已部署到 $webroot"
