# HTTPS domain subscription (private module, main script only).
# Current subscription is plain HTTP on a random port, served from
# $HOME/websbx/<token>/, protected only by the token in the URL.
# This module adds an HTTPS domain subscription on top, without
# breaking the HTTP fallback:
#   mode https:       ym + domain cert ready + (mem >= 256MB or our
#                     subscription Caddy already running) + caddy
#                     available + Caddy starts on 443. Caddy serves
#                     $HOME/websbx directly (file_server) with the
#                     domain cert in $HOME/agsbx/cert, so no separate
#                     subscription server is needed in this mode.
#   mode http-domain: ym set, but cert not ready, or memory gate
#                     fails, or caddy missing / 443 busy. Plain HTTP
#                     on ym:port/token, via the existing websbx server.
#   mode http-ip:     no ym. Original plain HTTP on IP:port/token.
# Rules, all deliberate:
# - Never self-signed HTTPS: a cert that does not parse or does not
#   match ym is not HTTPS, it is http-domain. Most subscription
#   clients reject self-signed HTTPS on update, so faking it would
#   break updates, not secure them.
# - Never start a second Caddy on 443 if one already binds it: a
#   failed start falls back to http-domain with a warning, it never
#   kills an existing Caddy (which may be the user's own service).
# - Memory gate uses the same detection as detect_certsrc
#   (/proc/meminfo MemTotal, < 262144 KB = 256MB), with an override
#   SUBHTTPS_MEM_KB for tests. The exception is only our own
#   subscription Caddy already running (no new process cost), not
#   any Caddy process, and not a system Caddy (which we must not
#   reconfigure or kill).
# - When https is up, the external plain-HTTP websbx server is
#   stopped and its @reboot cron removed, otherwise the same token
#   and files would still be fetchable in plain text and HTTPS
#   would gain nothing. The subscription Caddy gets its own
#   @reboot cron (subhttpsync) instead. When https falls back to
#   HTTP, the subscription Caddy is stopped, its cron removed, and
#   websbx (already started by the sub block before display) keeps
#   serving, as before.
# - Port 443 is managed separately from node ports (ufw.rules):
#   subhttps.443 is a marker file, present only while 443 was opened
#   by this module. Node ufw_sync never touches 443, and this module
#   never touches node rules, so a standalone subhttpsync on reboot
#   cannot delete node rules (it has no protocol variables in scope).
# - The subscription port (subpt, else the random port in subport.log)
#   is managed the same way, but only for HTTP subscriptions: when
#   websbx actually serves externally (http IP or http domain), its
#   port must be open or the subscription is unreachable behind ufw.
#   It is tracked by subhttps.subport (content "port/tcp"), NOT by
#   ufw.rules, because the port is only known after the sub block
#   runs (ufw_sync runs before it, so a first install would record
#   a stale port, and a port change on rep would be missed). When
#   the mode switches to https, websbx is stopped, so the old
#   subscription port is deleted; when the port changes, the old
#   rule is deleted and the new one opened. ufw_apply_saved calls
#   this manager too, so enabling ufw later and running ufwsync
#   opens the subscription port as well as the node ports.
# - All failures fall back, never abort: sync returns 0 even when
#   HTTPS is unavailable, so install/display/list never break.
subhttps_trim(){
  tr -d ' \t\r\n' 2>/dev/null
}
subhttps_read(){
  cat "$1" 2>/dev/null | subhttps_trim
}
subhttps_mem_kb(){
  if [ -n "${SUBHTTPS_MEM_KB:-}" ]; then echo "$SUBHTTPS_MEM_KB"; return; fi
  awk '/MemTotal/{print $2}' /proc/meminfo 2>/dev/null
}
subhttps_mem_ok(){
  local mem
  mem=$(subhttps_mem_kb)
  if [ -z "$mem" ]; then return 1; fi
  case "$mem" in ''|*[!0-9]*) return 1;; esac
  [ "$mem" -ge 262144 ]
}
subhttps_cert_ok(){
  local ym_c="$1" crt="$HOME/agsbx/cert/cert.crt" key="$HOME/agsbx/cert/private.key" txt=""
  [ -n "$ym_c" ] || return 1
  [ -s "$crt" ] && [ -s "$key" ] || return 1
  command -v openssl >/dev/null 2>&1 || return 1
  txt=$(openssl x509 -in "$crt" -noout -subject -ext subjectAltName 2>/dev/null || openssl x509 -in "$crt" -noout -subject 2>/dev/null)
  [ -n "$txt" ] || return 1
  case "$txt" in *"$ym_c"*) return 0;; *) return 1;; esac
}
subhttps_caddy_running(){
  local pid=""
  [ -f "$HOME/agsbx/subhttps.pid" ] || return 1
  pid=$(subhttps_read "$HOME/agsbx/subhttps.pid")
  case "$pid" in ''|*[!0-9]*) return 1;; esac
  kill -0 "$pid" 2>/dev/null || return 1
  if [ -f "/proc/$pid/cmdline" ]; then
    tr '\0' ' ' < "/proc/$pid/cmdline" 2>/dev/null | grep -q "Caddyfile.sub" || return 1
  fi
  return 0
}
subhttps_decide_mode(){
  local token="" ym_c=""
  token=$(subhttps_read "$HOME/agsbx/subtoken.log")
  ym_c=$(subhttps_read "$HOME/agsbx/ym")
  if [ -z "$token" ]; then echo "http-ip"; return; fi
  if [ -z "$ym_c" ]; then echo "http-ip"; return; fi
  if ! subhttps_cert_ok "$ym_c"; then echo "http-domain"; return; fi
  if ! subhttps_mem_ok && ! subhttps_caddy_running; then echo "http-domain"; return; fi
  if ! command -v caddy >/dev/null 2>&1 && ! subhttps_caddy_running; then echo "http-domain"; return; fi
  echo "https"
}
subhttps_write_conf(){
  local ym_c="$1"
  [ -n "$ym_c" ] || return 1
  mkdir -p "$HOME/agsbx" 2>/dev/null || true
  {
    echo "{"
    echo "  admin off"
    echo "}"
    echo "https://$ym_c {"
    echo "  tls \"$HOME/agsbx/cert/cert.crt\" \"$HOME/agsbx/cert/private.key\""
    echo "  root * \"$HOME/websbx\""
    echo "  file_server"
    echo "}"
  } > "$HOME/agsbx/Caddyfile.sub" 2>/dev/null || return 1
  return 0
}
subhttps_cert_hash(){
  sha256sum "$HOME/agsbx/cert/cert.crt" 2>/dev/null | awk '{print $1}'
}
subhttps_start_caddy(){
  local ym_c="$1" cur="" old=""
  if subhttps_caddy_running; then
    cur=$(subhttps_cert_hash)
    old=$(subhttps_read "$HOME/agsbx/subhttps.cert.hash")
    if [ -n "$cur" ] && [ "$cur" = "$old" ]; then return 0; fi
    subhttps_stop_caddy
  fi
  subhttps_write_conf "$ym_c" || return 1
  command -v caddy >/dev/null 2>&1 || return 1
  nohup caddy run --config "$HOME/agsbx/Caddyfile.sub" --adapter caddyfile > "$HOME/agsbx/subhttps.log" 2>&1 &
  echo $! > "$HOME/agsbx/subhttps.pid" 2>/dev/null || true
  sleep 2
  if subhttps_caddy_running; then
    cur=$(subhttps_cert_hash); [ -n "$cur" ] && echo "$cur" > "$HOME/agsbx/subhttps.cert.hash" 2>/dev/null || true
    return 0
  fi
  rm -f "$HOME/agsbx/subhttps.pid" 2>/dev/null || true
  return 1
}
subhttps_stop_caddy(){
  local pid=""
  if [ -f "$HOME/agsbx/subhttps.pid" ]; then
    pid=$(subhttps_read "$HOME/agsbx/subhttps.pid")
    case "$pid" in ''|*[!0-9]*) ;; *) kill "$pid" 2>/dev/null || true; sleep 1; kill -0 "$pid" 2>/dev/null && kill -9 "$pid" 2>/dev/null || true;; esac
    rm -f "$HOME/agsbx/subhttps.pid" "$HOME/agsbx/subhttps.cert.hash" 2>/dev/null || true
  fi
  if command -v pgrep >/dev/null 2>&1; then
    pgrep -f "Caddyfile.sub" 2>/dev/null | while IFS= read -r p || [ -n "$p" ]; do
      case "$p" in ''|*[!0-9]*) continue;; esac
      kill "$p" 2>/dev/null || true
    done
  fi
  return 0
}
subhttps_stop_websbx(){
  if command -v pgrep >/dev/null 2>&1; then
    pgrep -f "websbx" 2>/dev/null | while IFS= read -r p || [ -n "$p" ]; do
      case "$p" in ''|*[!0-9]*) continue;; esac
      kill "$p" 2>/dev/null || true
    done
  fi
  if command -v crontab >/dev/null 2>&1; then
    local tmp=""; tmp=$(mktemp 2>/dev/null) || return 0
    crontab -l 2>/dev/null | grep -v "websbx" > "$tmp" 2>/dev/null || true
    crontab "$tmp" 2>/dev/null || true
    rm -f "$tmp" 2>/dev/null || true
  fi
  return 0
}
subhttps_cron_install(){
  command -v crontab >/dev/null 2>&1 || return 0
  local tmp=""; tmp=$(mktemp 2>/dev/null) || return 0
  crontab -l 2>/dev/null | grep -v "argosbx-subhttps" > "$tmp" 2>/dev/null || true
  printf '@reboot sleep 10 && bash "$HOME/bin/agsbx" subhttpsync >/dev/null 2>&1  # argosbx-subhttps\n' >> "$tmp"
  crontab "$tmp" 2>/dev/null || true
  rm -f "$tmp" 2>/dev/null || true
  return 0
}
subhttps_cron_remove(){
  command -v crontab >/dev/null 2>&1 || return 0
  local tmp=""; tmp=$(mktemp 2>/dev/null) || return 0
  crontab -l 2>/dev/null | grep -v "argosbx-subhttps" > "$tmp" 2>/dev/null || true
  crontab "$tmp" 2>/dev/null || true
  rm -f "$tmp" 2>/dev/null || true
  return 0
}
subhttps_ufw_active(){
  if type ufw_is_active >/dev/null 2>&1; then ufw_is_active; return; fi
  command -v ufw >/dev/null 2>&1 || return 1
  ufw status 2>/dev/null | grep -q "Status: active"
}
# Multi-backend helpers for 443/subport. Markers are per backend:
# ufw keeps the old names (subhttps.443, subhttps.subport) for
# backward compat, firewalld uses subhttps.firewalld.*. When the
# firewall module is loaded, backends come from fw_active_backends;
# when this module is tested alone, fall back to the ufw check only,
# so the old sub-https tests (mock ufw, no firewall-cmd) still pass.
subhttps_fw_backends(){
  if type fw_active_backends >/dev/null 2>&1; then fw_active_backends; return; fi
  if subhttps_ufw_active; then echo "ufw"; fi
}
subhttps_fw_marker(){
  local kind="$1" backend="$2"
  case "$backend" in firewalld) echo "$HOME/agsbx/subhttps.firewalld.$kind";; *) echo "$HOME/agsbx/subhttps.$kind";; esac
}
subhttps_fw_zone(){
  local z=""; if type fw_firewalld_zone >/dev/null 2>&1; then fw_firewalld_zone; return; fi; z=$(firewall-cmd --get-default-zone 2>/dev/null | tr -d ' \t\r\n'); [ -n "$z" ] || z="public"; echo "$z"
}
subhttps_fw_allow(){
  local backend="$1" rule="$2"
  case "$backend" in
    ufw) ufw allow "$rule" >/dev/null 2>&1;;
    firewalld) firewall-cmd --permanent --zone="$(subhttps_fw_zone)" --add-port="$rule" >/dev/null 2>&1 && firewall-cmd --reload >/dev/null 2>&1;;
  esac
}
subhttps_fw_delete(){
  local backend="$1" rule="$2"
  case "$backend" in
    ufw) ufw --force delete allow "$rule" >/dev/null 2>&1;;
    firewalld) firewall-cmd --permanent --zone="$(subhttps_fw_zone)" --remove-port="$rule" >/dev/null 2>&1 && firewall-cmd --reload >/dev/null 2>&1;;
  esac
}
subhttps_fw_backend_cmd(){
  case "$1" in ufw) command -v ufw >/dev/null 2>&1;; firewalld) command -v firewall-cmd >/dev/null 2>&1;; esac
}
subhttps_manage_443(){
  local mode="$1" backend="" marker=""
  if [ "$mode" = "https" ]; then
    if [ -z "$(subhttps_fw_backends)" ]; then
      echo "ufw/firewalld 未运行，https 订阅的 443/tcp 未自动放行，开启后运行 agsbx fwsync 或 subhttpsync 重新同步"
      return 0
    fi
    for backend in $(subhttps_fw_backends); do
      marker=$(subhttps_fw_marker 443 "$backend")
      if [ -f "$marker" ]; then continue; fi
      if subhttps_fw_allow "$backend" "443/tcp"; then echo "443/tcp" > "$marker" 2>/dev/null || true; else echo "$backend 放行 443/tcp 失败（已忽略）"; fi
    done
  else
    for backend in ufw firewalld; do
      marker=$(subhttps_fw_marker 443 "$backend")
      if [ ! -f "$marker" ]; then continue; fi
      if subhttps_fw_backend_cmd "$backend"; then
        if subhttps_fw_delete "$backend" "443/tcp"; then rm -f "$marker" 2>/dev/null || true; else echo "$backend 删除 443/tcp 失败（已忽略，下次同步重试）"; fi
      else
        rm -f "$marker" 2>/dev/null || true
      fi
    done
  fi
  return 0
}
subhttps_manage_subport(){
  local mode="$1" subport="" desired="" backend="" marker="" old=""
  # HTTPS or no subscription: websbx is stopped (or never started),
  # so any previously opened subscription port must go, not stay
  # open for a server that no longer listens. This branch runs
  # before the token check on purpose, so del also cleans it up.
  # Delete from both backends regardless of active status: a stored
  # rule would become active again when that backend is enabled.
  if [ "$mode" = "https" ] || [ -z "$(subhttps_read "$HOME/agsbx/subtoken.log")" ]; then
    for backend in ufw firewalld; do
      marker=$(subhttps_fw_marker subport "$backend")
      if [ ! -f "$marker" ]; then continue; fi
      old=$(subhttps_read "$marker")
      if [ -z "$old" ]; then rm -f "$marker" 2>/dev/null || true; continue; fi
      if subhttps_fw_backend_cmd "$backend"; then
        if subhttps_fw_delete "$backend" "$old"; then rm -f "$marker" 2>/dev/null || true; else echo "$backend 删除订阅端口失败（已忽略，下次同步重试）"; fi
      else
        rm -f "$marker" 2>/dev/null || true
      fi
    done
    return 0
  fi
  subport=$(subhttps_read "$HOME/agsbx/subport.log")
  case "$subport" in ''|*[!0-9]*) return 0;; esac
  if [ "$subport" -lt 1 ] 2>/dev/null || [ "$subport" -gt 65535 ] 2>/dev/null; then return 0; fi
  desired="$subport/tcp"
  if [ -z "$(subhttps_fw_backends)" ]; then
    echo "ufw/firewalld 未运行，订阅端口 $desired 未自动放行，开启后运行 agsbx fwsync 或 subhttpsync 重新同步"
    return 0
  fi
  for backend in $(subhttps_fw_backends); do
    marker=$(subhttps_fw_marker subport "$backend")
    old=""; if [ -f "$marker" ]; then old=$(subhttps_read "$marker"); fi
    if [ "$old" = "$desired" ]; then continue; fi
    if [ -n "$old" ] && subhttps_fw_backend_cmd "$backend"; then
      subhttps_fw_delete "$backend" "$old" >/dev/null 2>&1 || echo "$backend 删除旧订阅端口失败（已忽略）：$old"
      rm -f "$marker" 2>/dev/null || true
    fi
    if subhttps_fw_allow "$backend" "$desired"; then echo "$desired" > "$marker" 2>/dev/null || true; else echo "$backend 放行订阅端口失败（已忽略）"; fi
  done
  return 0
}
sub_https_sync(){
  local token="" ym_c="" mode=""
  token=$(subhttps_read "$HOME/agsbx/subtoken.log")
  if [ -z "$token" ]; then return 0; fi
  ym_c=$(subhttps_read "$HOME/agsbx/ym")
  mode=$(subhttps_decide_mode)
  if [ "$mode" = "https" ]; then
    if subhttps_start_caddy "$ym_c"; then
      subhttps_stop_websbx
      subhttps_cron_install
      subhttps_manage_443 "https"
      subhttps_manage_subport "https"
      echo "https" > "$HOME/agsbx/subhttps.mode" 2>/dev/null || true
      echo "订阅已切换为 https 域名订阅：https://$ym_c/$token/"
      return 0
    fi
    echo "Caddy 启动失败（可能 443 已被占用），回退 http 域名订阅"
    mode="http-domain"
  fi
  subhttps_stop_caddy
  subhttps_cron_remove
  subhttps_manage_443 "$mode"
  subhttps_manage_subport "$mode"
  echo "$mode" > "$HOME/agsbx/subhttps.mode" 2>/dev/null || true
  if [ "$mode" = "http-domain" ]; then echo "订阅为 http 域名订阅（未满足 https 条件，见上文原因）"; else echo "订阅为 http IP 订阅"; fi
  return 0
}
sub_https_stop(){
  subhttps_stop_caddy
  subhttps_cron_remove
  subhttps_manage_443 "http-ip"
  subhttps_manage_subport "https"
  rm -f "$HOME/agsbx/subhttps.mode" "$HOME/agsbx/Caddyfile.sub" "$HOME/agsbx/subhttps.pid" "$HOME/agsbx/subhttps.cert.hash" "$HOME/agsbx/subhttps.log" "$HOME/agsbx/subhttps.443" "$HOME/agsbx/subhttps.subport" "$HOME/agsbx/subhttps.firewalld.443" "$HOME/agsbx/subhttps.firewalld.subport" 2>/dev/null || true
  return 0
}
sub_https_display(){
  local mode="" token="" subport="" subip="" ym_c=""
  mode=$(subhttps_read "$HOME/agsbx/subhttps.mode")
  token=$(subhttps_read "$HOME/agsbx/subtoken.log")
  subport=$(subhttps_read "$HOME/agsbx/subport.log")
  subip=$(subhttps_read "$HOME/agsbx/server_ip.log")
  ym_c=$(subhttps_read "$HOME/agsbx/ym")
  if [ -z "$token" ]; then return 0; fi
  if [ "$mode" = "https" ] && [ -n "$ym_c" ]; then
    if ! subhttps_caddy_running; then
      if [ -n "$ym_c" ] && [ -n "$subport" ]; then mode="http-domain"; else mode="http-ip"; fi
    fi
  fi
  if [ "$mode" = "https" ] && [ -n "$ym_c" ]; then
    echo "**********************************************************"
    echo "Clash/Mihomo https 域名订阅地址：https://$ym_c/$token/clmi.yaml"
    echo "Sing-box https 域名订阅地址：https://$ym_c/$token/sbox.json"
    echo "聚合协议 https 域名订阅地址：https://$ym_c/$token/jhsub.txt"
    echo "**********************************************************"
    return 0
  fi
  if [ "$mode" = "http-domain" ] && [ -n "$ym_c" ] && [ -n "$subport" ]; then
    echo "**********************************************************"
    echo "Clash/Mihomo域名订阅地址：http://$ym_c:$subport/$token/clmi.yaml"
    echo "Sing-box域名订阅地址：http://$ym_c:$subport/$token/sbox.json"
    echo "聚合协议域名订阅地址：http://$ym_c:$subport/$token/jhsub.txt"
    echo "**********************************************************"
    return 0
  fi
  if [ -s "$HOME/agsbx/subport.log" ] && [ -n "$subport" ] && [ -n "$subip" ]; then
    if ps -ef 2>/dev/null | grep "$subport" | grep -v grep >/dev/null; then
      echo "**********************************************************"
      echo "Clash/Mihomo本地IP订阅地址：http://$subip:$subport/$token/clmi.yaml"
      echo "Sing-box本地IP订阅地址：http://$subip:$subport/$token/sbox.json"
      echo "聚合协议本地IP订阅地址：http://$subip:$subport/$token/jhsub.txt"
      echo "**********************************************************"
    fi
  fi
  return 0
}
command -v register_hook >/dev/null 2>&1 && {
  register_hook post_start sub_https_sync
  register_hook on_uninstall sub_https_stop
}
# ufw firewall sync (private module, main script only).
# Rule: only when ufw is already active. This module NEVER turns
# ufw on by itself, never opens SSH (22), cert ports (80/443) for
# nodes, or the Argo local port. Only node inbound ports are opened
# here, and only with the transport the inbound actually uses,
# so nothing is over-opened. The subscription port and the HTTPS
# 443 port are NOT node ports: they are managed separately by the
# sub-https module (subhttps.subport / subhttps.443 markers), because
# the subscription port is only known after the sub block runs and
# it changes with the subscription mode (HTTP: open the websbx port;
# HTTPS: close it, open 443 instead). ufw_apply_saved calls those
# managers (guarded, so this module alone still works) so that
# enabling ufw later and running ufwsync opens everything, not just
# the node ports:
#   tcp only: vlpt (incl. comma instances), xhpt, vxpt, vwpt, xcpt, nvpt, anpt, arpt, vmpt, vmtls
#   udp only: xupt, tupt, hypt
#   tcp+udp:  sspt, sopt
# Why xcpt is tcp only even though its display name says TCP/UDP:
# the direct inbound uses alpn h2/http/1.1 (TCP); the UDP variants in
# the display are CDN links, not the direct port. Opening UDP for it
# would be over-opening. Why xupt is udp only: its direct inbound
# uses alpn h3 only (QUIC/HTTP3). Why sspt/sopt are both: their
# inbounds listen on both (Xray socks has udp:true, sing-box
# shadowsocks/socks inbounds default to both when no network is set).
# State: $HOME/agsbx/ufw.rules, one "port/proto" per line, written
# by ufw_sync even when ufw is inactive, so a later `agsbx ufwsync`
# can apply it after the user enables ufw, and so `del` can delete
# exactly the rules this script opened, never the user's own rules.
# All failures are warnings only: a ufw failure must never abort
# an install or an uninstall.
ufw_is_active(){
  command -v ufw >/dev/null 2>&1 || return 1
  ufw status 2>/dev/null | grep -q "Status: active"
}
_ufw_port(){
  local v="$1" f="$2" p
  p="$v"
  case "$p" in ''|*[!0-9]*) p="";; esac
  if [ -z "$p" ] && [ -n "$f" ] && [ -f "$f" ]; then
    p=$(tr -d ' \t\r\n' < "$f" 2>/dev/null)
    case "$p" in ''|*[!0-9]*) p="";; esac
  fi
  if [ -n "$p" ] && [ "$p" -ge 1 ] 2>/dev/null && [ "$p" -le 65535 ] 2>/dev/null; then
    echo "$p"
  fi
}
_ufw_emit(){
  local proto_var="$1" proto_name="$2" port_var="$3" port_file="$4" protos="$5" p pr
  if [ "$proto_var" != "$proto_name" ]; then return 0; fi
  p=$(_ufw_port "$port_var" "$port_file")
  if [ -z "$p" ]; then return 0; fi
  for pr in $protos; do echo "$p/$pr"; done
}
ufw_desired_rules(){
  local _f _n _p
  _ufw_emit "$vlp" vlpt "$port_vl_re" "$HOME/agsbx/port_vl_re" "tcp"
  if [ -n "$vlpt_more" ]; then
    local _mp="" _moldifs="$IFS"; IFS=','; for _mp in $vlpt_more; do _mp=$(printf '%s' "$_mp" | xargs 2>/dev/null || printf '%s' "$_mp"); case "$_mp" in ''|*[!0-9]*) ;; *) echo "$_mp/tcp";; esac; done; IFS="$_moldifs"
  fi
  # vlpt instances from a comma list may be random (empty item or
  # "random"): their ports are only in port files, not in vlpt_more,
  # so also emit every vlpt tag actually present in xr/sb.json
  # (N >= 2, including instance 2 when it came from vlpt_more).
  # sort -u in the callers dedupes against the emits above.
  for _f in "$HOME/agsbx"/port_vl_re[0-9]*; do
    [ -f "$_f" ] || continue
    case "$_f" in *port_vl_re) continue;; esac
    _n="${_f##*port_vl_re}"
    if grep -q "\"tag\":\"reality-vision-$_n\"" "$HOME/agsbx/xr.json" 2>/dev/null || grep -q "\"tag\": \"vl-reality-sb-$_n\"" "$HOME/agsbx/sb.json" 2>/dev/null; then
      _p=$(_ufw_port "" "$_f"); [ -n "$_p" ] && echo "$_p/tcp"
    fi
  done
  _ufw_emit "$xhp" xhpt "$port_xh" "$HOME/agsbx/port_xh" "tcp"
  _ufw_emit "$vxp" vxpt "$port_vx" "$HOME/agsbx/port_vx" "tcp"
  _ufw_emit "$vwp" vwpt "$port_vw" "$HOME/agsbx/port_vw" "tcp"
  _ufw_emit "$xup" xupt "$port_xu" "$HOME/agsbx/port_xu" "udp"
  _ufw_emit "$xcp" xcpt "$port_xc" "$HOME/agsbx/port_xc" "tcp"
  _ufw_emit "$nvp" nvpt "$port_nv" "$HOME/agsbx/port_nv" "tcp"
  _ufw_emit "$tup" tupt "$port_tu" "$HOME/agsbx/port_tu" "udp"
  _ufw_emit "$anp" anpt "$port_an" "$HOME/agsbx/port_an" "tcp"
  _ufw_emit "$arp" arpt "$port_ar" "$HOME/agsbx/port_ar" "tcp"
  _ufw_emit "$ssp" sspt "$port_ss" "$HOME/agsbx/port_ss" "tcp udp"
  _ufw_emit "$hyp" hypt "$port_hy2" "$HOME/agsbx/port_hy2" "udp"
  _ufw_emit "$vmp" vmpt "$port_vm_ws" "$HOME/agsbx/port_vm_ws" "tcp"
  _ufw_emit "$vmt" vmtls "$port_vm_tls" "$HOME/agsbx/port_vm_tls" "tcp"
  _ufw_emit "$sop" sopt "$port_so" "$HOME/agsbx/port_so" "tcp udp"
  # Other protocols comma more instances: fixed ports from *_more,
  # plus a tag scan for random ports (their ports are only in port
  # files, not in *_more). Both fw_sync backends use this function,
  # so ufw and firewalld open the same set. sort -u dedupes.
  local _mn="" _mv="" _moldifs2="$IFS"
  for _mn in xhpt_more vxpt_more vwpt_more xupt_more xcpt_more nvpt_more tupt_more anpt_more arpt_more sspt_more hypt_more vmpt_more vmtls_more sopt_more; do
    _mv=$(eval "printf '%s' \"\${$_mn:-}\"" 2>/dev/null || printf '%s' "")
    IFS=','; for _p in $_mv; do _p=$(printf '%s' "$_p" | xargs 2>/dev/null || printf '%s' "$_p"); case "$_p" in ''|*[!0-9]*) ;; *) case "$_mn" in xupt_more|tupt_more|hypt_more) echo "$_p/udp";; sspt_more|sopt_more) echo "$_p/tcp"; echo "$_p/udp";; *) echo "$_p/tcp";; esac;; esac; done; IFS="$_moldifs2"
  done
  # Tag scan: prefix -> transport -> tag base. Grep allows an
  # optional space after the colon because xr/sb.json tag formats
  # differ ("tag":"x" vs "tag": "x").
  local _pfx _protos _tag _cfg _pr
  for _spec in "port_xh:tcp:xhttp-reality:xr" "port_vx:tcp:vless-xhttp:xr" "port_vw:tcp:vless-ws:xr" "port_xu:udp:xhttp-h3:xr" "port_xc:tcp:xhttp-h23:xr" "port_nv:tcp:naive-sb:sb" "port_tu:udp:tuic5-sb:sb" "port_an:tcp:anytls-sb:sb" "port_ar:tcp:anyreality-sb:sb" "port_ss:tcp udp:ss-2022:sb" "port_hy2:udp:hy2:both" "port_vm_ws:tcp:vmess:both" "port_vm_tls:tcp:vmess-tls:both" "port_so:tcp udp:socks5:both"; do
    _pfx="${_spec%%:*}"; _protos=$(printf '%s' "$_spec" | cut -d: -f2); _tag=$(printf '%s' "$_spec" | cut -d: -f3); _cfg=$(printf '%s' "$_spec" | cut -d: -f4)
    for _f in "$HOME/agsbx"/"$_pfx"[0-9]*; do
      [ -f "$_f" ] || continue
      _n="${_f##*$_pfx}"
      _p=$(_ufw_port "" "$_f"); [ -n "$_p" ] || continue
      case "$_cfg" in
        xr) grep -Eq "\"tag\": *\"$_tag-$_n\"" "$HOME/agsbx/xr.json" 2>/dev/null || continue;;
        sb) grep -Eq "\"tag\": *\"$_tag-$_n\"" "$HOME/agsbx/sb.json" 2>/dev/null || continue;;
        both) if grep -Eq "\"tag\": *\"$_tag-xr-$_n\"" "$HOME/agsbx/xr.json" 2>/dev/null || grep -Eq "\"tag\": *\"$_tag-sb-$_n\"" "$HOME/agsbx/sb.json" 2>/dev/null; then :; else continue; fi;;
      esac
      for _pr in $_protos; do echo "$_p/$_pr"; done
    done
  done
}
_ufw_fallback_rules(){
  local spec f protos p pr
  for spec in "port_vl_re:tcp" "port_vl_re2:tcp" "port_xh:tcp" "port_vx:tcp" "port_vw:tcp" "port_xu:udp" "port_xc:tcp" "port_nv:tcp" "port_tu:udp" "port_an:tcp" "port_ar:tcp" "port_ss:tcp udp" "port_hy2:udp" "port_vm_ws:tcp" "port_vm_tls:tcp" "port_so:tcp udp"; do
    f="${spec%%:*}"; protos="${spec#*:}"
    p=$(_ufw_port "" "$HOME/agsbx/$f")
    if [ -z "$p" ]; then continue; fi
    for pr in $protos; do echo "$p/$pr"; done
  done
  # vlpt extra instances: port_vl_re2 is in the spec list above;
  # port_vl_re3, port_vl_re4, ... are not, so scan them here.
  for f in "$HOME/agsbx"/port_vl_re[0-9]*; do
    [ -f "$f" ] || continue
    case "$f" in *port_vl_re|*port_vl_re2) continue;; esac
    p=$(_ufw_port "" "$f")
    [ -n "$p" ] && echo "$p/tcp"
  done
  # Other protocols more instances: same scan, with their transport.
  local _pfx2 _protos2 _pr2
  for _spec2 in "port_xh:tcp" "port_vx:tcp" "port_vw:tcp" "port_xu:udp" "port_xc:tcp" "port_nv:tcp" "port_tu:udp" "port_an:tcp" "port_ar:tcp" "port_ss:tcp udp" "port_hy2:udp" "port_vm_ws:tcp" "port_vm_tls:tcp" "port_so:tcp udp"; do
    _pfx2="${_spec2%%:*}"; _protos2="${_spec2#*:}"
    for f in "$HOME/agsbx"/"$_pfx2"[0-9]*; do
      [ -f "$f" ] || continue
      p=$(_ufw_port "" "$f"); [ -n "$p" ] || continue
      for _pr2 in $_protos2; do echo "$p/$_pr2"; done
    done
  done
}
ufw_sync(){
  local state="$HOME/agsbx/ufw.rules" tmp added deleted r
  mkdir -p "$HOME/agsbx" 2>/dev/null || true
  tmp="$state.tmp.$$"
  ufw_desired_rules | sort -u > "$tmp" 2>/dev/null || true
  if ! ufw_is_active; then
    mv "$tmp" "$state" 2>/dev/null || true
    echo "ufw 未开启，已记录节点端口规则，开启 ufw 后运行 agsbx ufwsync 重新同步"
    return 0
  fi
  added=0; deleted=0
  if [ -f "$state" ]; then
    while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      if ! grep -qx "$r" "$tmp" 2>/dev/null; then
        if ufw --force delete allow "$r" >/dev/null 2>&1; then deleted=$((deleted + 1)); else echo "ufw 删除规则失败（已忽略）：$r"; fi
      fi
    done < "$state"
  fi
  while IFS= read -r r || [ -n "$r" ]; do
    case "$r" in '') continue;; esac
    if [ ! -f "$state" ] || ! grep -qx "$r" "$state" 2>/dev/null; then
      if ufw allow "$r" >/dev/null 2>&1; then added=$((added + 1)); else echo "ufw 放行失败（已忽略）：$r"; fi
    fi
  done < "$tmp"
  mv "$tmp" "$state" 2>/dev/null || true
  echo "ufw 已同步节点端口规则（新增 $added 条，删除 $deleted 条）"
  return 0
}
ufw_apply_saved(){
  local state="$HOME/agsbx/ufw.rules" n=0 r
  if [ ! -s "$state" ]; then
    echo "没有记录的 ufw 规则，请先安装一次"
    return 0
  fi
  if ! ufw_is_active; then
    echo "ufw 未开启，已记录的规则未放行，开启 ufw 后再次运行 agsbx ufwsync"
    return 0
  fi
  while IFS= read -r r || [ -n "$r" ]; do
    case "$r" in '') continue;; esac
    if ufw allow "$r" >/dev/null 2>&1; then n=$((n + 1)); else echo "ufw 放行失败（已忽略）：$r"; fi
  done < "$state"
  # Subscription ports, by current mode (guarded: this module is
  # also tested alone, without the sub-https module loaded).
  if type subhttps_manage_subport >/dev/null 2>&1 || type subhttps_manage_443 >/dev/null 2>&1; then
    local submode=""; submode=$(tr -d ' \t\r\n' < "$HOME/agsbx/subhttps.mode" 2>/dev/null); [ -n "$submode" ] || submode="http-ip"
    if type subhttps_manage_subport >/dev/null 2>&1; then subhttps_manage_subport "$submode"; fi
    if type subhttps_manage_443 >/dev/null 2>&1; then subhttps_manage_443 "$submode"; fi
  fi
  echo "ufw 已按记录放行 $n 条规则"
  return 0
}
ufw_cleanup(){
  local state="$HOME/agsbx/ufw.rules" r
  if [ -f "$state" ]; then
    if command -v ufw >/dev/null 2>&1; then
      while IFS= read -r r || [ -n "$r" ]; do
        case "$r" in '') continue;; esac
        ufw --force delete allow "$r" >/dev/null 2>&1 || true
      done < "$state"
    fi
    rm -f "$state"
    return 0
  fi
  if command -v ufw >/dev/null 2>&1; then
    _ufw_fallback_rules | sort -u | while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      ufw --force delete allow "$r" >/dev/null 2>&1 || true
    done
  fi
  return 0
}
# --- Layered firewall: ufw + firewalld auto, raw iptables/nft prompt ---
# Why layered: ufw and firewalld both have a clear active state and a
# safe per-port API, so they can be managed automatically. Raw
# iptables/nft have no single on/off switch (see fw_raw_blocking):
# the ruleset is the firewall, and inserting into it can break the
# user's ordering (APPEND after a final DROP never matches) and
# persistence (Debian netfilter-persistent, RHEL iptables service,
# Alpine rc-service all differ), plus Docker/fail2ban chains. So raw
# rules are detected and printed, never auto-inserted. Cloud security
# groups and panel firewalls (BT/CSF) live outside this VM and cannot
# be seen or changed from here at all, so they get a checklist only.
# Safety rules from the ufw module still hold for every backend:
# never turn a firewall on, never open 22/Argo-local ports, never
# delete a rule that is not in our own state file, failures warn only.
fw_firewalld_active(){
  command -v firewall-cmd >/dev/null 2>&1 || return 1
  # Exact match on purpose: firewall-cmd --state prints "not running"
  # when stopped, and that string contains "running", so grep -q
  # "running" would wrongly report an inactive firewalld as active.
  [ "$(firewall-cmd --state 2>/dev/null)" = "running" ]
}
fw_firewalld_zone(){
  local z=""; z=$(firewall-cmd --get-default-zone 2>/dev/null | tr -d ' \t\r\n'); [ -n "$z" ] || z="public"; echo "$z"
}
# Prints one active backend per line: ufw, firewalld, or both.
# Both active is unusual (they fight over the same nft/iptables
# backend); we apply to both so the node works either way, and warn.
fw_active_backends(){
  if ufw_is_active; then echo "ufw"; fi
  if fw_firewalld_active; then echo "firewalld"; fi
}
fw_allow_rule(){
  local backend="$1" rule="$2"
  case "$backend" in
    ufw) ufw allow "$rule" >/dev/null 2>&1;;
    firewalld) firewall-cmd --permanent --zone="$(fw_firewalld_zone)" --add-port="$rule" >/dev/null 2>&1;;
  esac
}
fw_delete_rule(){
  local backend="$1" rule="$2"
  case "$backend" in
    ufw) ufw --force delete allow "$rule" >/dev/null 2>&1;;
    firewalld) firewall-cmd --permanent --zone="$(fw_firewalld_zone)" --remove-port="$rule" >/dev/null 2>&1;;
  esac
}
fw_reload_backend(){
  case "$1" in firewalld) firewall-cmd --reload >/dev/null 2>&1 || true;; esac
}
# firewalld mirror of ufw_sync, same diff semantics, state file
# $HOME/agsbx/firewalld.rules. Reload once at the end, not per port.
firewalld_sync(){
  local state="$HOME/agsbx/firewalld.rules" tmp added deleted r
  mkdir -p "$HOME/agsbx" 2>/dev/null || true
  tmp="$state.tmp.$$"
  ufw_desired_rules | sort -u > "$tmp" 2>/dev/null || true
  if ! fw_firewalld_active; then
    mv "$tmp" "$state" 2>/dev/null || true
    echo "firewalld 未运行，已记录节点端口规则，启动 firewalld 后运行 agsbx fwsync 重新同步"
    return 0
  fi
  added=0; deleted=0
  if [ -f "$state" ]; then
    while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      if ! grep -qx "$r" "$tmp" 2>/dev/null; then
        if fw_delete_rule firewalld "$r"; then deleted=$((deleted + 1)); else echo "firewalld 删除规则失败（已忽略）：$r"; fi
      fi
    done < "$state"
  fi
  while IFS= read -r r || [ -n "$r" ]; do
    case "$r" in '') continue;; esac
    if [ ! -f "$state" ] || ! grep -qx "$r" "$state" 2>/dev/null; then
      if fw_allow_rule firewalld "$r"; then added=$((added + 1)); else echo "firewalld 放行失败（已忽略）：$r"; fi
    fi
  done < "$tmp"
  fw_reload_backend firewalld
  mv "$tmp" "$state" 2>/dev/null || true
  echo "firewalld 已同步节点端口规则（新增 $added 条，删除 $deleted 条）"
  return 0
}
firewalld_apply_saved(){
  local state="$HOME/agsbx/firewalld.rules" n=0 r
  if [ ! -s "$state" ]; then echo "没有记录的 firewalld 规则，请先安装一次"; return 0; fi
  if ! fw_firewalld_active; then echo "firewalld 未运行，已记录的规则未放行，启动后再次运行 agsbx fwsync"; return 0; fi
  while IFS= read -r r || [ -n "$r" ]; do
    case "$r" in '') continue;; esac
    if fw_allow_rule firewalld "$r"; then n=$((n + 1)); else echo "firewalld 放行失败（已忽略）：$r"; fi
  done < "$state"
  fw_reload_backend firewalld
  if type subhttps_manage_subport >/dev/null 2>&1 || type subhttps_manage_443 >/dev/null 2>&1; then
    local submode=""; submode=$(tr -d ' \t\r\n' < "$HOME/agsbx/subhttps.mode" 2>/dev/null); [ -n "$submode" ] || submode="http-ip"
    if type subhttps_manage_subport >/dev/null 2>&1; then subhttps_manage_subport "$submode"; fi
    if type subhttps_manage_443 >/dev/null 2>&1; then subhttps_manage_443 "$submode"; fi
  fi
  echo "firewalld 已按记录放行 $n 条规则"
  return 0
}
firewalld_cleanup(){
  local state="$HOME/agsbx/firewalld.rules" r
  if [ -f "$state" ]; then
    if command -v firewall-cmd >/dev/null 2>&1; then
      while IFS= read -r r || [ -n "$r" ]; do
        case "$r" in '') continue;; esac
        fw_delete_rule firewalld "$r" || true
      done < "$state"
      fw_reload_backend firewalld
    fi
    rm -f "$state"
    return 0
  fi
  if command -v firewall-cmd >/dev/null 2>&1; then
    _ufw_fallback_rules | sort -u | while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      fw_delete_rule firewalld "$r" || true
    done
    fw_reload_backend firewalld
  fi
  return 0
}
# Raw iptables/nft blocking detection. Returns 0 when a blocking
# ruleset is present. It is per-chain, not "is iptables installed":
# an empty ruleset with policy ACCEPT is not blocking, and Docker /
# fail2ban chains outside INPUT do not count, because only INPUT
# decides whether a node port is reachable from outside.
fw_raw_blocking(){
  local out=""
  if command -v iptables >/dev/null 2>&1; then
    out=$(iptables -S INPUT 2>/dev/null)
    case "$out" in
      "-P INPUT DROP"*|"-P INPUT REJECT"*) return 0;;
    esac
    if echo "$out" | grep -Eq -- "-j (DROP|REJECT)( |$)"; then return 0; fi
  fi
  if command -v nft >/dev/null 2>&1; then
    out=$(nft list ruleset 2>/dev/null)
    if echo "$out" | grep -Eq "hook input.*policy drop|hook input.*policy reject"; then return 0; fi
  fi
  return 1
}
# Ready-to-paste raw rules, for the prompt path only. INSERT, not
# APPEND: a rule appended after a final DROP never matches.
fw_print_raw_prompt(){
  local r=""
  echo "检测到裸 iptables/nft 在拦 INPUT（无 ufw/firewalld 在跑），脚本未自动插规则，请手动放行："
  if [ -f "$HOME/agsbx/ufw.rules" ]; then
    while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      echo "  iptables -I INPUT -p ${r#*/} --dport ${r%/*} -j ACCEPT"
    done < "$HOME/agsbx/ufw.rules"
  else
    ufw_desired_rules | sort -u | while IFS= read -r r || [ -n "$r" ]; do
      case "$r" in '') continue;; esac
      echo "  iptables -I INPUT -p ${r#*/} --dport ${r%/*} -j ACCEPT"
    done
  fi
  echo "  持久化（按发行版二选一）：Debian/Ubuntu 用 netfilter-persistent save；RHEL 系用 service iptables save；Alpine 用 rc-service iptables save；nft 用 nft list ruleset > /etc/nftables.conf"
  return 0
}
fw_print_cloud_checklist(){
  echo "云厂商安全组 / 面板防火墙（宝塔、CSF 等）脚本无法自动放行，请在控制台手动放行以下节点端口："
  if [ -f "$HOME/agsbx/ufw.rules" ]; then
    while IFS= read -r r || [ -n "$r" ]; do case "$r" in '') continue;; esac; echo "  $r"; done < "$HOME/agsbx/ufw.rules"
  else
    ufw_desired_rules | sort -u | while IFS= read -r r || [ -n "$r" ]; do case "$r" in '') continue;; esac; echo "  $r"; done
  fi
  return 0
}
# Unified sync, called from the install flow instead of ufw_sync.
# ufw_sync itself is kept unchanged for backward compat and for the
# ufw-only tests; fw_sync is the layered entry point.
fw_sync(){
  local backends="" n=0 b=""
  backends=$(fw_active_backends)
  if [ -z "$backends" ]; then
    ufw_sync
    if fw_raw_blocking; then fw_print_raw_prompt; fi
    fw_print_cloud_checklist
    return 0
  fi
  for b in $backends; do n=$((n + 1)); done
  if [ "$n" -gt 1 ]; then echo "警告：ufw 与 firewalld 同时在运行，已对两者都同步，长期建议只留一个管理器"; fi
  if ufw_is_active; then ufw_sync; fi
  if fw_firewalld_active; then firewalld_sync; fi
  fw_print_cloud_checklist
  return 0
}
fw_apply_saved(){
  if ufw_is_active; then ufw_apply_saved; fi
  if fw_firewalld_active; then firewalld_apply_saved; fi
  if ! ufw_is_active && ! fw_firewalld_active; then
    echo "没有在运行的防火墙后端（ufw/firewalld），已记录的规则未放行"
    if fw_raw_blocking; then fw_print_raw_prompt; fi
    return 0
  fi
  return 0
}
fw_cleanup(){
  ufw_cleanup
  firewalld_cleanup
  return 0
}
fw_status(){
  local b=""
  echo "防火墙后端："
  if [ -z "$(fw_active_backends)" ]; then echo "  （无 ufw/firewalld 在运行）"; else for b in $(fw_active_backends); do echo "  $b 在运行"; done; fi
  echo "已记录节点端口："
  if [ -f "$HOME/agsbx/ufw.rules" ]; then while IFS= read -r b || [ -n "$b" ]; do case "$b" in '') continue;; esac; echo "  ufw: $b"; done < "$HOME/agsbx/ufw.rules"; fi
  if [ -f "$HOME/agsbx/firewalld.rules" ]; then while IFS= read -r b || [ -n "$b" ]; do case "$b" in '') continue;; esac; echo "  firewalld: $b"; done < "$HOME/agsbx/firewalld.rules"; fi
  if fw_raw_blocking; then echo "裸 iptables/nft：检测到 INPUT 在拦（见上文手动命令）"; else echo "裸 iptables/nft：未检测到 INPUT 拦截"; fi
  fw_print_cloud_checklist
  return 0
}
command -v register_hook >/dev/null 2>&1 && {
  register_hook post_start fw_sync
  register_hook on_uninstall fw_cleanup
}
url='https://raw.githubusercontent.com/qytang2014/argosbx/main/argosbx.sh'
case "${*##* }" in list|del|upx|ups|upa|res|certwatch|certrestart|ufwsync|fwsync|fwstatus|subhttpsync) ;; *)
cmd=""
for v in uuid vlpt vmpt vmtls vwpt hypt tupt xhpt vxpt anpt arpt sspt sopt nvpt xupt xcpt reym cdnym argo agn agk warp name oap ym alns certmode certsrc vlpt_kernel egress_nodes egress_bind egress_rules egress_add cfip hyjpt ippz sub subid subpt; do
[ -n "${!v+x}" ] && cmd+="$v=\"${!v}\" "
done
main="bash <(curl -Ls $url)"
cmd+="$main${*:+ $*}"
[ "$cmd" != "$main" ] && echo "$cmd" > "$HOME/agsbx/sh.txt"
;; esac
[ -z "${vlpt+x}" ] || vlp=yes
[ -z "${vmpt+x}" ] || { vmp=yes; vmag=yes; }
[ -z "${vmtls+x}" ] || vmt=yes
[ -z "${vwpt+x}" ] || { vwp=yes; vmag=yes; }
[ -z "${hypt+x}" ] || hyp=yes
[ -z "${tupt+x}" ] || tup=yes
[ -z "${xhpt+x}" ] || xhp=yes
[ -z "${vxpt+x}" ] || vxp=yes
[ -z "${anpt+x}" ] || anp=yes
[ -z "${sspt+x}" ] || ssp=yes
[ -z "${arpt+x}" ] || arp=yes
[ -z "${sopt+x}" ] || sop=yes
[ -z "${warp+x}" ] || wap=yes
[ -z "${nvpt+x}" ] || nvp=yes
[ -z "${xupt+x}" ] || xup=yes
[ -z "${xcpt+x}" ] || xcp=yes
if find /proc/*/exe -type l 2>/dev/null | grep -E '/proc/[0-9]+/exe' | xargs -r readlink 2>/dev/null | grep -Eq 'agsbx/(s|x)' || pgrep -f 'agsbx/(s|x)' >/dev/null 2>&1; then
if [ "$1" = "rep" ]; then
[ "$xcp" = yes ] || [ "$xup" = yes ] || [ "$nvp" = yes ] || [ "$vwp" = yes ] || [ "$sop" = yes ] || [ "$vxp" = yes ] || [ "$ssp" = yes ] || [ "$vlp" = yes ] || [ "$vmp" = yes ] || [ "$vmt" = yes ] || [ "$hyp" = yes ] || [ "$tup" = yes ] || [ "$xhp" = yes ] || [ "$anp" = yes ] || [ "$arp" = yes ] || { echo "提示：rep重置协议时，请在脚本前至少设置一个协议变量哦，再见！💣"; exit; }
fi
else
[ "$1" = "del" ] || [ "$xcp" = yes ] || [ "$xup" = yes ] || [ "$nvp" = yes ] || [ "$vwp" = yes ] || [ "$sop" = yes ] || [ "$vxp" = yes ] || [ "$ssp" = yes ] || [ "$vlp" = yes ] || [ "$vmp" = yes ] || [ "$vmt" = yes ] || [ "$hyp" = yes ] || [ "$tup" = yes ] || [ "$xhp" = yes ] || [ "$anp" = yes ] || [ "$arp" = yes ] || { echo "提示：未安装argosbx脚本，请在脚本前至少设置一个协议变量哦，再见！💣"; exit; }
fi
# vlpt comma list (private module, runs at top level, before exports).
# The generator now has only one vlpt field: its value is a comma list.
# Comma count + 1 = instance count, an empty item = a random port.
#   ""            -> 1 instance, random
#   "10001"       -> 1 instance, port 10001
#   ","           -> 2 instances, both random
#   "10001,"      -> instance 1 = 10001, instance 2 = random
#   ",10002"      -> instance 1 = random, instance 2 = 10002
#   "10001,10002" -> 2 instances, fixed ports
#   ",,"          -> 3 instances, all random
# This expansion turns a comma list into vlpt (first item) + vlpt_more
# (rest items) for the existing loop, so install/display/ufw/egress
# need no other change, and sh.txt (saved before this runs) still
# shows the original comma command. A trailing comma would otherwise
# vanish in vlpt_more ("" means "no extra instance"), so it becomes
# the sentinel "random", which the loop treats as a random port.
# vlpt2 / vlpt_more are NO LONGER user inputs (removed 2026-10-28:
# QUINN confirmed they were never used on another machine). They are
# cleared here unconditionally, before the comma expansion, so a
# command that still passes vlpt2= / vlpt_more= simply does nothing
# with them -- no second instance, no warning, no compatibility path.
# vlpt_more below is INTERNAL only, set by this expansion.
vlpt2=""; vlpt_more=""; vlp2=""
case "$vlpt" in *,*)
  _vlpt_comma_rest="${vlpt#*,}"
  vlpt="${vlpt%%,*}"
  if [ -z "$_vlpt_comma_rest" ]; then vlpt_more="random"; else vlpt_more="$_vlpt_comma_rest"; fi
  ;;
esac
# Other protocols comma list (private module, runs at top level, before exports).
# Same semantics as vlpt comma: comma count + 1 = instance count, an
# empty item = a random port. Each protocol variable is split into
# itself (first item) + <proto>_more (rest items). A trailing comma
# becomes the sentinel "random", because an empty _more string would
# mean "no extra instance" downstream. The loop modules for each
# protocol (proto-more-xray/sb/auto) consume the _more list.
# sh.txt is saved before this runs, so it still shows the original
# comma command; vars.env saves the expanded _more lists.
# *_more are NO LONGER user inputs (same treatment as vlpt_more,
# 2026-10-28): they are cleared here unconditionally, before the
# comma expansion, so a command that still passes xhpt_more= /
# sspt_more= etc. simply does nothing with them. The _more lists
# below are INTERNAL only, set by the comma expansion itself, and
# vars.env keeps saving those internally generated lists so `add`
# can still carry extra instances.
for _pc_var in xhpt vxpt vwpt xupt xcpt nvpt tupt anpt arpt sspt hypt vmpt vmtls sopt; do
  eval "${_pc_var}_more=\"\""
done
for _pc_var in xhpt vxpt vwpt xupt xcpt nvpt tupt anpt arpt sspt hypt vmpt vmtls sopt; do
  _pc_val=$(eval "printf '%s' \"\${$_pc_var:-}\"") 2>/dev/null || _pc_val=""
  case "$_pc_val" in *,*)
    _pc_rest="${_pc_val#*,}"
    _pc_first="${_pc_val%%,*}"
    if [ -z "$_pc_rest" ]; then _pc_rest="random"; fi
    eval "$_pc_var=\"\$_pc_first\""
    eval "${_pc_var}_more=\"\$_pc_rest\""
    ;;
  esac
done
unset _pc_var _pc_val _pc_rest _pc_first
export uuid=${uuid:-''}
export port_vl_re=${vlpt:-''}
export port_vm_ws=${vmpt:-''}
export port_vm_tls=${vmtls:-''}
export port_vw=${vwpt:-''}
export port_hy2=${hypt:-''}
export port_tu=${tupt:-''}
export port_xh=${xhpt:-''}
export port_vx=${vxpt:-''}
export port_an=${anpt:-''}
export port_ar=${arpt:-''}
export port_ss=${sspt:-''}
export port_so=${sopt:-''}
export port_nv=${nvpt:-''}
export port_xu=${xupt:-''}
export port_xc=${xcpt:-''}
export ym_vl_re=${reym:-''}
export cdnym=${cdnym:-''}
export ym=${ym:-''}
export alns=${alns:-''}
export CERT_DIR="$HOME/agsbx/cert"
export CERT_CRT="$CERT_DIR/cert.crt"
export CERT_KEY="$CERT_DIR/private.key"
# cert_migrate_paths: one-time move from the old $HOME/argosbx locations
# to the unified $HOME/agsbx tree. Copies only, never deletes the old
# files (old configs / acme renewals may still reference them until the
# next install regenerates json). Idempotent: a second call is a no-op
# except for the acme install-path update, which is itself idempotent.
cert_migrate_paths(){
  if [ -s "$HOME/argosbx/cert/cert.crt" ]; then
    mkdir -p "$HOME/agsbx/cert" 2>/dev/null || true
    [ -s "$HOME/agsbx/cert/cert.crt" ] || cp -P "$HOME/argosbx/cert/cert.crt" "$HOME/agsbx/cert/cert.crt" 2>/dev/null || true
    [ -s "$HOME/agsbx/cert/private.key" ] || { [ -s "$HOME/argosbx/cert/private.key" ] && cp -P "$HOME/argosbx/cert/private.key" "$HOME/agsbx/cert/private.key" 2>/dev/null || true; }
    if [ -x "$HOME/.acme.sh/acme.sh" ] && [ -n "$ym" ]; then
      "$HOME/.acme.sh/acme.sh" --install-cert -d "$ym" --key-file "$HOME/agsbx/cert/private.key" --fullchain-file "$HOME/agsbx/cert/cert.crt" --reloadcmd "bash $HOME/bin/agsbx certrestart" >/dev/null 2>&1 || true
    fi
  fi
  if [ -s "$HOME/agsbx/cert.crt" ] && [ ! -s "$HOME/agsbx/selfsigned/cert.crt" ]; then
    mkdir -p "$HOME/agsbx/selfsigned" 2>/dev/null || true
    cp -P "$HOME/agsbx/cert.crt" "$HOME/agsbx/selfsigned/cert.crt" 2>/dev/null || true
    [ -s "$HOME/agsbx/private.key" ] && cp -P "$HOME/agsbx/private.key" "$HOME/agsbx/selfsigned/private.key" 2>/dev/null || true
  fi
  if [ -s "$HOME/argosbx/Caddyfile" ] && [ ! -s "$HOME/agsbx/Caddyfile" ]; then
    cp "$HOME/argosbx/Caddyfile" "$HOME/agsbx/Caddyfile" 2>/dev/null || true
  fi
}
export certmode=${certmode:-''}
export certsrc=${certsrc:-''}
# certsrc：证书来源，空=自动，caddy=Caddy，acme=acme.sh。
# 自动逻辑：显式选择优先；否则总内存小于 256MB 时优先 acme（低内存机器不常驻 Caddy）；否则有 caddy 命令时用 Caddy，否则用 acme。
# acme 分支不自动安装 acme.sh，需预先安装在 $HOME/.acme.sh/acme.sh，否则等待超时后回落自签。
detect_certsrc(){
  if [ "$certsrc" = "caddy" ]; then echo "caddy"; return; fi
  if [ "$certsrc" = "acme" ]; then echo "acme"; return; fi
  local mem_kb=""
  mem_kb=$(awk '/MemTotal/{print $2}' /proc/meminfo 2>/dev/null)
  if [ -n "$mem_kb" ] && [ "$mem_kb" -lt 262144 ]; then echo "acme"; return; fi
  if command -v caddy >/dev/null 2>&1; then echo "caddy"; return; fi
  echo "acme"
}
# certmode：证书验证方式，空=自动，http=强制 HTTP，dns=强制 DNS。
# 自动逻辑：显式选择优先；否则 Argo 开启时按已代理处理；否则查 ym 的 DNS，若解析 IP 已知且不等于本机 IP 则按已代理处理，否则 HTTP。
# 注意：本机 IP 以 $HOME/agsbx/server_ip.log 为准，若该文件不存在则不做 DNS 对比，避免误判为已代理。
detect_certmode(){
  if [ "$certmode" = "http" ]; then echo "http"; return; fi
  if [ "$certmode" = "dns" ]; then echo "dns"; return; fi
  if [ -n "$argo" ] || [ -n "$agn" ]; then echo "dns"; return; fi
  local dns_ip="" srv_ip=""
  srv_ip=$(cat "$HOME/agsbx/server_ip.log" 2>/dev/null | tr -d " \t\r\n")
  if [ -n "$srv_ip" ]; then
    dns_ip=$(getent hosts "$ym" 2>/dev/null | awk '{print $1}' | head -n1)
    if [ -z "$dns_ip" ] && command -v dig >/dev/null 2>&1; then dns_ip=$(dig +short "$ym" A 2>/dev/null | head -n1); fi
    if [ -n "$dns_ip" ] && [ "$dns_ip" != "$srv_ip" ]; then echo "dns"; return; fi
  fi
  echo "http"
}
# write_caddyfile：按验证方式写 Caddyfile。优先写系统位置 /etc/caddy/argosbx.caddyfile，并让主配置 import 它（先备份主配置，已有 import 行则不重复加）；无 root / /etc/caddy 不可写时回落到 $HOME/agsbx/Caddyfile（单个文件，不另建目录）。
# 本函数只写配置，不安装 Caddy；是否启动/重载由调用方尽力尝试，失败不中断后续等待与回落。生成路径保存在全局变量 caddyfile_path 和 $HOME/agsbx/caddyfile_path。
write_caddyfile(){
  local conf_file=""
  caddyfile_path=""
  if [ "$(id -u 2>/dev/null)" = "0" ]; then
    mkdir -p /etc/caddy 2>/dev/null || true
    if [ -w /etc/caddy ]; then
      conf_file="/etc/caddy/argosbx.caddyfile"
      if [ -f /etc/caddy/Caddyfile ]; then
        if ! grep -q "argosbx.caddyfile" /etc/caddy/Caddyfile 2>/dev/null; then
          cp /etc/caddy/Caddyfile "/etc/caddy/Caddyfile.bak.$(date +%Y%m%d%H%M%S)" 2>/dev/null || true
          printf "\nimport argosbx.caddyfile\n" >> /etc/caddy/Caddyfile
        fi
      else
        printf "import argosbx.caddyfile\n" > /etc/caddy/Caddyfile
      fi
    fi
  fi
  if [ -z "$conf_file" ]; then
    mkdir -p "$HOME/agsbx"
    conf_file="$HOME/agsbx/Caddyfile"
  fi
  if [ "$certmode_selected" = "dns" ]; then
    printf "%s {\n  tls {\n    dns cloudflare {env.CLOUDFLARE_API_TOKEN}\n  }\n  respond \"ok\"\n}\n" "$ym" > "$conf_file"
  else
    printf "%s {\n  respond \"ok\"\n}\n" "$ym" > "$conf_file"
  fi
  chmod 644 "$conf_file" 2>/dev/null || true
  caddyfile_path="$conf_file"
  echo "$conf_file" > "$HOME/agsbx/caddyfile_path" 2>/dev/null || true
  echo "Caddyfile 已生成：$conf_file（验证方式：$certmode_selected）"
}

# ensure_acme：acme.sh 不存在时自动安装（官方安装脚本，装到 $HOME/.acme.sh，写续期 cron）。不自动安装则返回 1，调用方继续等待、超时回落自签，不中断主脚本。
ensure_acme(){
  [ -x "$HOME/.acme.sh/acme.sh" ] && return 0
  local tmpdir=""
  tmpdir=$(mktemp -d 2>/dev/null) || return 1
  if ! curl -fsSL https://get.acme.sh -o "$tmpdir/acme-install.sh" 2>/dev/null; then rm -rf "$tmpdir"; echo "acme.sh 安装脚本下载失败"; return 1; fi
  if ! sh "$tmpdir/acme-install.sh" >/dev/null 2>&1; then rm -rf "$tmpdir"; echo "acme.sh 安装失败"; return 1; fi
  rm -rf "$tmpdir"
  [ -x "$HOME/.acme.sh/acme.sh" ] || { echo "acme.sh 安装后仍未找到可执行文件"; return 1; }
  echo "acme.sh 已自动安装：$HOME/.acme.sh/acme.sh"
  return 0
}
# ensure_caddy_download：Caddy 不存在时下载用户预编译版（Coraza + Cloudflare），非交互、带备份与校验，失败返回 1 不中断主脚本。
# 配置来源（优先级）：密码文件 /etc/caddy/.files_auth_pass（已确认路径，600 权限），否则环境变量 CADDY_DOWNLOAD_PASS；URL 默认 https://files.quinn.de5.net/，可用 CADDY_DOWNLOAD_URL 覆盖；用户名默认 tom，可用 CADDY_DOWNLOAD_USER 覆盖。
# 不再先装官方版再覆盖；只在需要时停掉已有服务，验过新二进制（版本 + Cloudflare + Coraza 模块）才替换，验不过用备份恢复。
ensure_caddy_download(){
  [ "$(id -u 2>/dev/null)" = "0" ] || { echo "下载 Caddy 需要 root 权限（写 /usr/bin 与 /etc/caddy）"; return 1; }
  local base_url="${CADDY_DOWNLOAD_URL:-https://files.quinn.de5.net/}"
  local web_user="${CADDY_DOWNLOAD_USER:-tom}"
  local pass_file="/etc/caddy/.files_auth_pass"
  local web_pass=""
  mkdir -p /etc/caddy 2>/dev/null || true
  if [ -s "$pass_file" ]; then web_pass=$(cat "$pass_file"); elif [ -n "$CADDY_DOWNLOAD_PASS" ]; then web_pass="$CADDY_DOWNLOAD_PASS"; else echo "Caddy 预编译下载缺少密码：请先将密码写入 $pass_file（600 权限）或设置 CADDY_DOWNLOAD_PASS"; return 1; fi
  local caddy_bin=""
  case "$cpu" in amd64) caddy_bin="caddy_x86_64";; arm64) caddy_bin="caddy_arm";; *) echo "不支持的架构：$cpu"; return 1;; esac
  [[ "$base_url" != */ ]] && base_url="${base_url}/"
  local final_url="${base_url}caddy/${caddy_bin}"
  local tmpdir="" netrc=""
  tmpdir=$(mktemp -d 2>/dev/null) || return 1
  netrc="$tmpdir/netrc"
  printf "machine %s\nlogin %s\npassword %s\n" "$(printf "%s" "$final_url" | awk -F/ '{print $3}')" "$web_user" "$web_pass" > "$netrc"
  chmod 600 "$netrc"
  echo "正在拉取预编译 Caddy：$final_url"
  if ! curl --netrc-file "$netrc" -fL --retry 3 --connect-timeout 15 -o "$tmpdir/caddy" "$final_url" 2>/dev/null; then rm -rf "$tmpdir"; echo "Caddy 下载失败，请检查 URL、用户名、密码或网络"; return 1; fi
  rm -f "$netrc"
  chmod +x "$tmpdir/caddy"
  if ! "$tmpdir/caddy" version >/dev/null 2>&1; then rm -rf "$tmpdir"; echo "下载的 Caddy 无法运行（架构或文件损坏）"; return 1; fi
  if ! "$tmpdir/caddy" list-modules 2>/dev/null | grep -q "cloudflare"; then rm -rf "$tmpdir"; echo "下载的 Caddy 缺少 Cloudflare 模块，拒绝替换"; return 1; fi
  if ! "$tmpdir/caddy" list-modules 2>/dev/null | grep -q "coraza"; then rm -rf "$tmpdir"; echo "下载的 Caddy 缺少 Coraza 模块，拒绝替换"; return 1; fi
  if command -v systemctl >/dev/null 2>&1; then systemctl stop caddy 2>/dev/null || true; fi
  if [ -f /usr/bin/caddy ]; then cp /usr/bin/caddy /usr/bin/caddy.bak 2>/dev/null || true; fi
  if ! mv -f "$tmpdir/caddy" /usr/bin/caddy; then rm -rf "$tmpdir"; echo "替换 /usr/bin/caddy 失败"; return 1; fi
  chmod 755 /usr/bin/caddy 2>/dev/null || true
  setcap cap_net_bind_service=+ep /usr/bin/caddy 2>/dev/null || true
  if ! /usr/bin/caddy version >/dev/null 2>&1; then [ -f /usr/bin/caddy.bak ] && mv -f /usr/bin/caddy.bak /usr/bin/caddy; rm -rf "$tmpdir"; echo "新 Caddy 校验失败，已恢复备份"; return 1; fi
  rm -rf "$tmpdir"
  if command -v systemctl >/dev/null 2>&1 && systemctl list-unit-files caddy.service >/dev/null 2>&1; then systemctl start caddy 2>/dev/null || echo "Caddy 服务启动失败，请手动检查 systemctl status caddy"; fi
  echo "预编译 Caddy 下载并替换成功"
  return 0
}
# 域名证书：固定目录 $HOME/agsbx/cert（Caddy 时内为指向 Caddy 证书存储的软链接，acme 时直接安装到该目录）。
# domain_cert_valid：检查是否已有 $ym 的有效证书（两文件存在非空、可解析、域名匹配、剩余有效期 >7 天）。
# 有则返回 0，调用方跳过 --issue 直接复用，避免"已有证书还报发证失败"的误导。
domain_cert_valid(){
  [ -n "$ym" ] || return 1
  [ -s "$CERT_CRT" ] && [ -s "$CERT_KEY" ] || return 1
  command -v openssl >/dev/null 2>&1 || return 1
  local cert_text=""
  cert_text=$(openssl x509 -in "$CERT_CRT" -noout -subject -ext subjectAltName 2>/dev/null || openssl x509 -in "$CERT_CRT" -noout -subject 2>/dev/null) || return 1
  case "$cert_text" in *"$ym"*) ;; *) return 1;; esac
  openssl x509 -in "$CERT_CRT" -noout -checkend 604800 >/dev/null 2>&1 || return 1
  return 0
}
# wait_domain_cert：等待最长 300 秒，每 15 秒检查一次；校验两文件存在且非空、非断链、证书可解析且域名匹配 ym。返回 0=就绪，1=未就绪（调用方超时回落自签）。
wait_domain_cert(){
  [ -n "$ym" ] || return 1
  local waited=0 cert_text=""
  while [ "$waited" -lt 300 ]; do
    if [ -s "$CERT_CRT" ] && [ -s "$CERT_KEY" ] && [ -e "$CERT_CRT" ] && [ -e "$CERT_KEY" ]; then
      if command -v openssl >/dev/null 2>&1; then
        cert_text=$(openssl x509 -in "$CERT_CRT" -noout -subject -ext subjectAltName 2>/dev/null || openssl x509 -in "$CERT_CRT" -noout -subject 2>/dev/null)
        case "$cert_text" in *"$ym"*) echo "域名证书已就绪：$ym（$CERT_DIR）"; return 0;; esac
      fi
    fi
    [ "$waited" -eq 0 ] && echo "等待域名证书就绪：$ym（最长 300 秒，每 15 秒检查一次，目录 $CERT_DIR）"
    sleep 15
    waited=$((waited + 15))
  done
  echo "域名证书超时未就绪：$ym，300 秒后回落自签证书"
  return 1
}
# Cert renewal auto-restart: Caddy has no post-renewal hook, and acme.sh
# renewal alone does not restart sing-box/xray, so both paths are covered:
#  - acme: --install-cert --reloadcmd "bash $HOME/bin/agsbx certrestart"
#    runs immediately on acme renewal (see modules/cert-main.sh).
#  - Caddy (and as a backstop for acme): a daily cron entry
#    "bash $HOME/bin/agsbx certwatch" checks the cert hash in the fixed
#    dir and restarts only the kernels whose config uses that cert.
# Rules: hash is sha256 of the cert file (following symlinks); a change
# is acted on only if the new cert parses and, when a domain is known,
# matches that domain; an invalid cert never updates the recorded hash
# and never triggers a restart, so the next run retries instead of
# losing the change. Restart uses the existing sbrestart/xrestart
# functions, which handle systemd / OpenRC / nohup the same way the
# rest of the script does. If a kernel was stopped, sbrestart/xrestart
# will start it again; that is intentional on renewal.
cert_cert_hash(){ sha256sum "$CERT_CRT" 2>/dev/null | awk '{print $1}'; }
cert_uses_domain_cert(){
  { [ -f "$HOME/agsbx/sb.json" ] && grep -q 'agsbx/cert' "$HOME/agsbx/sb.json" 2>/dev/null; } || \
  { [ -f "$HOME/agsbx/xr.json" ] && grep -q 'agsbx/cert' "$HOME/agsbx/xr.json" 2>/dev/null; }
}
cert_restart(){
  cert_uses_domain_cert || { echo "域名证书未被 sing-box/xray 配置使用，跳过重启"; return 0; }
  if [ -f "$HOME/agsbx/sb.json" ] && grep -q 'agsbx/cert' "$HOME/agsbx/sb.json" 2>/dev/null; then
    echo "证书已更新，重启 sing-box"; sbrestart
  fi
  if [ -f "$HOME/agsbx/xr.json" ] && grep -q 'agsbx/cert' "$HOME/agsbx/xr.json" 2>/dev/null; then
    echo "证书已更新，重启 xray"; xrestart
  fi
  # Subscription Caddy also serves this cert: restart it when the
  # cert hash changed (sub_https_sync is a no-op when the hash is
  # unchanged, and guarded here so cert-watch tests sourcing only
  # this module do not fail when sub-https is not loaded).
  if type sub_https_sync >/dev/null 2>&1; then sub_https_sync; fi
}
cert_watch(){
  [ -s "$CERT_CRT" ] || return 0
  local ym_watch="" cur="" old="" cert_text=""
  ym_watch="${ym:-$(cat "$HOME/agsbx/ym" 2>/dev/null)}"
  # validity warning: the hash check below only fires when the cert CHANGES.
  # A silently failed renewal (broken acme hook, Caddy not reloading) leaves
  # the hash unchanged until expiry day. Warn when <7 days remain, daily.
  if command -v openssl >/dev/null 2>&1; then
    if ! openssl x509 -in "$CERT_CRT" -noout -checkend 604800 2>/dev/null; then
      echo "⚠ 域名证书（${ym_watch:-未知域名}）7 天内过期但未检测到续期，请检查 acme.sh / Caddy 续期是否正常"
    fi
  fi
  cur=$(cert_cert_hash); [ -n "$cur" ] || return 0
  if [ ! -f "$HOME/agsbx/cert.hash" ]; then echo "$cur" > "$HOME/agsbx/cert.hash"; return 0; fi
  old=$(cat "$HOME/agsbx/cert.hash" 2>/dev/null)
  [ "$cur" != "$old" ] || return 0
  if command -v openssl >/dev/null 2>&1; then
    cert_text=$(openssl x509 -in "$CERT_CRT" -noout -subject -ext subjectAltName 2>/dev/null || openssl x509 -in "$CERT_CRT" -noout -subject 2>/dev/null)
    [ -n "$cert_text" ] || { echo "新证书无法解析，跳过重启，下次再试"; return 0; }
    if [ -n "$ym_watch" ]; then case "$cert_text" in *"$ym_watch"*) ;; *) echo "新证书域名不匹配 $ym_watch，跳过重启，下次再试"; return 0;; esac; fi
  fi
  echo "$cur" > "$HOME/agsbx/cert.hash"
  echo "域名证书已变化（$ym_watch），重启相关内核"
  cert_restart
}
cert_install_watch(){
  local cur="" tmp=""
  cur=$(cert_cert_hash); [ -n "$cur" ] && echo "$cur" > "$HOME/agsbx/cert.hash"
  command -v crontab >/dev/null 2>&1 || { echo "未找到 crontab，证书续期 watcher 未安装，acme 续期仍可通过 reloadcmd 重启"; return 0; }
  tmp=$(mktemp 2>/dev/null) || return 0
  crontab -l 2>/dev/null | grep -v 'argosbx-certwatch' > "$tmp" || true
  printf '0 3 * * * bash "$HOME/bin/agsbx" certwatch >/dev/null 2>&1  # argosbx-certwatch\n' >> "$tmp"
  crontab "$tmp" 2>/dev/null || echo "证书续期 watcher cron 安装失败，请手动添加：0 3 * * * bash \$HOME/bin/agsbx certwatch"
  rm -f "$tmp"
  echo "证书续期 watcher 已安装：每天 03:00 检查证书变化并重启相关内核"
}
cert_remove_watch(){
  command -v crontab >/dev/null 2>&1 || return 0
  local tmp=""; tmp=$(mktemp 2>/dev/null) || return 0
  crontab -l 2>/dev/null | grep -v 'argosbx-certwatch' > "$tmp" || true
  crontab "$tmp" 2>/dev/null || true
  rm -f "$tmp"
}
command -v register_hook >/dev/null 2>&1 && {
  register_hook on_uninstall cert_remove_watch
}
