                    "shortIds": ["$short_id_x"]
                }
            },
          "sniffing": {
          "enabled": true,
          "destOverride": ["http", "tls", "quic"],
          "metadataOnly": false
      }
    },
EOF
  _vlpt_more_idx=$((_vlpt_more_idx + 1))
  [ "$_vlpt_more_rest" = "__DONE__" ] && break
done
fi

