if [ -e "$HOME/agsbx/xr.json" ]; then
cat >> "$HOME/agsbx/xr.json" <<EOF
        {
            "tag": "vmess-tls-xr",
            "listen": "::",
            "port": ${port_vm_tls},
            "protocol": "vmess",
            "settings": {
                "clients": [
                    {
                        "id": "${uuid}"
                    }
                ]
            },
            "streamSettings": {
                "network": "ws",
                "security": "tls",
                "tlsSettings": {
                    "certificates": [
                        {
                            "certificateFile": "$certificateHTA",
                            "keyFile": "$keyHTA"
                        }
                    ]
                },
                "wsSettings": {
                  "path": "${uuid}-vmtls"
            }
        },
